INSERT INTO `gossip_menu_option_locale` (`MenuID`,`OptionID`,`Locale`,`OptionText`,`BoxText`) VALUES
(2562,0,'deDE','Ich sehe mich nur mal um.',''),
(2743,0,'deDE','Bildet mich aus.',''),
(2946,0,'deDE','Wenn ich das nächste Mal auf eines von diesen Viechern treffe, dann werde ich daran denken.',''),
(2947,0,'deDE','Ach?',''),
(2948,0,'deDE','Eine Sache muss ich einfach wissen. Wie seid Ihr in diesem Anzug auf die Toilette gegangen?',''),
(2949,0,'deDE','Nur, damit ich das richtig verstehe: Ihr seid also mit diesem... diesem Lavaanzug da in geschmolzener Lava herumgeschwommen, auf dem Rücken? Ja? Und dann hat Euch einfach so, aus heiterem Himmel, diese Bestie hier in einem Stück verschluckt?',''),
(3067,0,'deDE','Ich möchte ausgebildet werden.',''),
(3070,0,'deDE','Bildet mich aus.',''),
(3072,0,'deDE','Bildet mich aus.',''),
(3364,0,'deDE','Ja, das bin ich.',''),
(3365,0,'deDE','Ja. Ja, ich verstehe.',''),
(3366,0,'deDE','Fahrt bitte fort.',''),
(3367,0,'deDE','Ras Frostwas? Wer soll denn das sein?',''),
(3368,0,'deDE','Und was ist das für ein Plan?',''),
(3369,0,'deDE','Wen muss ich töten?',''),
(3370,0,'deDE','Das ist entmutigend zu hören. Gibt es irgendetwas, das ich tun kann, um das zu beenden?',''),
(3371,0,'deDE','Unmöglich.',''),
(3372,0,'deDE','Erzählt mir vom Kult der Verdammten.',''),
(3842,0,'deDE','Wo befindet sich der Zeppelin gerade?',''),
(3862,0,'deDE','Du hast gut gekämpft, Geist. Ich bitte dich, gib mir die Kraft deines Körpers und die Kraft deines Herzens.',''),
(3862,1,'deDE','Du hast gut gekämpft, Geist. Ich bitte dich, gib mir die Kraft deines Körpers und die Kraft deines Herzens.',''),
(4186,0,'deDE','Bildet mich aus.',''),
(4263,0,'deDE','Bildet mich aus.',''),
(4843,0,'deDE','Bildet mich aus.',''),
(4944,0,'deDE','Was wisst Ihr über das Gasthaus "Zur Süßen Ruh"?',''),
(5283,1,'deDE','Ich hätte gerne einen Platz im Stall für meinen Begleiter.',''),
(5346,0,'deDE','Erzählt mir mehr über die Geschichte von Remulos und Zaetar.',''),
(5851,0,'deDE','Häuptling Bluthuf, dies mag nach einer sonderbaren Bitte klingen... aber ich habe da einen jungen Schützling, der recht schüchtern ist. Ihr seid ein Held für ihn, deshalb bat er mich Euch um einen Hufabdruck zu bitten.',''),
